def comps(g, coords, val):
    allowed=set(coords); seen=set(); out=[]
    for p in allowed:
        if p in seen or g[p[0]][p[1]]!=val: continue
        st=[p]; seen.add(p); cc=[]
        while st:
            r,c=st.pop(); cc.append((r,c))
